def eval_expr(s):
    """Evaluate an arithmetic expression string with non-negative integers,
    + - * / ( ), and unary minus. '/' is float division. Returns a float.
    No eval/exec/ast. Raises ValueError on malformed input."""
    # Tokenize
    tokens = []
    i, n = 0, len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            tokens.append(("num", int(s[i:j])))
            i = j
        elif c in "+-*/()":
            tokens.append(("op", c))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c!r}")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def take():
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError("Unexpected end of expression")
        tok = tokens[pos]
        pos += 1
        return tok

    # Grammar (recursive descent):
    #   expr    := term (('+' | '-') term)*
    #   term    := factor (('*' | '/') factor)*
    #   factor  := ('+' | '-') factor | primary
    #   primary := NUMBER | '(' expr ')'
    def parse_expr():
        value = parse_term()
        while True:
            tok = peek()
            if tok is not None and tok[0] == "op" and tok[1] in "+-":
                op = take()[1]
                right = parse_term()
                value = value + right if op == "+" else value - right
            else:
                return value

    def parse_term():
        value = parse_factor()
        while True:
            tok = peek()
            if tok is not None and tok[0] == "op" and tok[1] in "*/":
                op = take()[1]
                right = parse_factor()
                value = value * right if op == "*" else value / right
            else:
                return value

    def parse_factor():
        tok = peek()
        if tok is not None and tok[0] == "op" and tok[1] in "+-":
            op = take()[1]
            value = parse_factor()
            return -value if op == "-" else value
        return parse_primary()

    def parse_primary():
        tok = take()
        if tok[0] == "num":
            return float(tok[1])
        if tok[0] == "op" and tok[1] == "(":
            value = parse_expr()
            if peek() is None or peek()[1] != ")":
                raise ValueError("Missing closing parenthesis")
            take()
            return value
        raise ValueError(f"Unexpected token: {tok!r}")

    result = parse_expr()
    if peek() is not None:
        raise ValueError(f"Unexpected token: {peek()!r}")
    return float(result)
```

