def topo_count(n, edges):
    """Number of distinct topological orderings of a DAG with nodes 0..n-1."""
    pred = [0] * n
    for u, v in edges:
        pred[v] |= 1 << u
    full = 1 << n
    dp = [0] * full
    dp[0] = 1
    for mask in range(full):
        if dp[mask] == 0:
            continue
        for v in range(n):
            if (mask >> v) & 1 == 0 and (pred[v] & ~mask) == 0:
                dp[mask | (1 << v)] += dp[mask]
    return dp[full - 1]
